begin;
-- All fixtures are rolled back, including notifications. Requires database admin.
create function pg_temp.assert(ok boolean,label text) returns void language plpgsql as $$begin if ok is not true then raise exception 'TEST FAILED: %',label;end if;end$$;
create temporary table test_context(k text primary key,v text);
grant all on test_context to authenticated;
insert into test_context select 'a',id::text from public.profiles where slot=1;
insert into test_context select 'b',id::text from public.profiles where slot=2;
select pg_temp.assert((select count(*)=2 from public.profiles),'exactly two seats');
select pg_temp.assert(not has_table_privilege('anon','public.meetings','select'),'anon cannot read meetings');
select pg_temp.assert(not has_table_privilege('authenticated','public.meetings','update'),'no direct meeting updates');
select pg_temp.assert(not has_column_privilege('authenticated','public.profiles','slot','update'),'cannot reassign account slots');
select pg_temp.assert(not has_function_privilege('anon','public.respond_meeting(uuid,integer,text,timestamptz,timestamptz,text,boolean)','execute'),'anon cannot invoke transitions');
select pg_temp.assert((select not public from storage.buckets where id='memories'),'photo bucket is private');
do $$begin begin insert into auth.users(id,email) values(gen_random_uuid(),'intruder@example.org');raise exception 'TEST FAILED: third account allowed';exception when raise_exception then if SQLERRM not like '%exactly two keys%' then raise;end if;end;end$$;
set local role authenticated;
select set_config('request.jwt.claims',json_build_object('sub',(select v from test_context where k='a'),'role','authenticated')::text,true);
select pg_temp.assert((select count(*)=2 from public.profiles),'member sees both profiles');
insert into test_context values('schedule',public.save_schedule(jsonb_build_object('owner',auth.uid(),'day','2026-11-02','start_time','09:00','end_time','18:00','kind','college','state','unavailable','weekdays',jsonb_build_array(1,3),'interval_weeks',2,'until_day',null,'exceptions','[]'::jsonb,'is_private',true),'PRIVATE TEST TITLE')::text);
insert into test_context select 'm',id::text from public.meetings where false;
with m as(insert into public.meetings(proposer,start_at,end_at,place)values(auth.uid(),now()+interval '1 day',now()+interval '1 day 90 minutes','E2E SQL rollback') returning id)insert into test_context select 'm',id::text from m;
do $$begin begin perform public.respond_meeting((select v::uuid from test_context where k='m'),1,'accepted');raise exception 'TEST FAILED: self accept';exception when raise_exception then if SQLERRM not like '%второй человек%' then raise;end if;end;end$$;
select set_config('request.jwt.claims',json_build_object('sub',(select v from test_context where k='b'),'role','authenticated')::text,true);
select pg_temp.assert((select count(*)=0 from public.schedule_details where id=(select v::uuid from test_context where k='schedule')),'private title hidden from partner');
select pg_temp.assert((select kind='busy' from public.schedules where id=(select v::uuid from test_context where k='schedule')),'private type masked');
select pg_temp.assert((select count(*)=0 from public.notifications where recipient<>auth.uid()),'notification recipient RLS');
select pg_temp.assert((public.respond_meeting((select v::uuid from test_context where k='m'),1,'accepted')).status='accepted','other person accepts');
do $$begin begin perform public.respond_meeting((select v::uuid from test_context where k='m'),1,'cancelled');raise exception 'TEST FAILED: stale transition';exception when raise_exception then if SQLERRM not like 'STALE:%' then raise;end if;end;end$$;
select pg_temp.assert((public.respond_meeting((select v::uuid from test_context where k='m'),2,'cancelled')).status='cancelled','cancel confirmed meeting');
with m as(insert into public.meetings(proposer,start_at,end_at,place)values(auth.uid(),now()+interval '2 day',now()+interval '2 day 90 minutes','E2E SQL counter rollback') returning id)insert into test_context select 'counter',id::text from m;
select set_config('request.jwt.claims',json_build_object('sub',(select v from test_context where k='a'),'role','authenticated')::text,true);
select pg_temp.assert((public.respond_meeting((select v::uuid from test_context where k='counter'),1,'counter',now()+interval '3 day',now()+interval '3 day 90 minutes')).status='counter','counter proposal remains pending');
do $$begin begin perform public.respond_meeting((select v::uuid from test_context where k='counter'),2,'accepted');raise exception 'TEST FAILED: self counter accept';exception when raise_exception then if SQLERRM not like '%второй человек%' then raise;end if;end;end$$;
select set_config('request.jwt.claims',json_build_object('sub',(select v from test_context where k='b'),'role','authenticated')::text,true);
select pg_temp.assert((public.respond_meeting((select v::uuid from test_context where k='counter'),2,'declined')).status='declined','decline counter proposal');
select set_config('request.jwt.claims','{"sub":"00000000-0000-0000-0000-000000000099","role":"authenticated"}',true);
select pg_temp.assert((select count(*)=0 from public.profiles),'outsider profile RLS');
select pg_temp.assert((select count(*)=0 from public.schedules),'outsider schedule RLS');
select pg_temp.assert((select count(*)=0 from public.meetings),'outsider meetings RLS');
select pg_temp.assert((select count(*)=0 from public.memories),'outsider memories RLS');
select pg_temp.assert((select count(*)=0 from public.interactions),'outsider interactions RLS');
do $$begin begin perform public.respond_meeting((select v::uuid from test_context where k='m'),3,'accepted');raise exception 'TEST FAILED: outsider transition';exception when raise_exception then if SQLERRM<>'Access denied' then raise;end if;end;end$$;
reset role;
select 'PASS: membership, grants, auth allowlist, private details, state machine, stale edits, counter proposals, recipient RLS, storage privacy; all fixtures rolled back' as result;
rollback;
